// WF03b step 1 — unpack statements[] from WF02b into N items, one per statement.
// Carry target_folder_id / target_folder_name / callback_url from the parent
// onto every per-statement item so Drive upload and WF04b can read them.
const inp = $input.first() && $input.first().json;
if (!inp) return [];
const statements = inp.statements || [];
const target_folder_id = inp.target_folder_id || '';
const target_folder_name = inp.target_folder_name || '';
const callback_url = inp.callback_url || '';
return statements.map(s => ({
  json: {
    ...s,
    target_folder_id: s.target_folder_id || target_folder_id,
    target_folder_name: s.target_folder_name || target_folder_name,
    callback_url: s.callback_url || callback_url
  }
}));

// WF03b step 2 — compute dedup_period_hash + the Drive filename.
const crypto = require('crypto');
const s = $json;
const bank = s.bank || 'generic';
const ps = s.period_start || 'nodate';
const pe = s.period_end || 'nodate';
const period_hash = crypto.createHash('md5').update(`${bank}|${ps}|${pe}`).digest('hex');
const sshort = (s.statement_id || '').slice(0, 8) || 'noid';
const rawName = `${bank}_${ps}_${pe}_${sshort}.pdf`;
const filename = rawName.replace(/[^A-Za-z0-9._\-Ѐ-ӿ]/g, '_');
return { json: { ...s, dedup_period_hash: period_hash, drive_filename: filename } };

// WF03b step 4 — assemble statements-sheet row from Drive upload response + meta.
const driveResp = $json;
const meta = $('Compute Period Hash + Filename').item.json;
const webViewLink = driveResp.webViewLink || (driveResp.id ? `https://drive.google.com/file/d/${driveResp.id}/view` : null);
return {
  json: {
    session_id: meta.session_id,
    chat_id: meta.chat_id,
    statement_id: meta.statement_id,
    bank: meta.bank,
    period_start: meta.period_start,
    period_end: meta.period_end,
    currency: meta.currency,
    opening_balance: meta.opening_balance,
    closing_balance: meta.closing_balance,
    dedup_period_hash: meta.dedup_period_hash,
    drive_url: webViewLink,
    processed_at: new Date().toISOString(),
    transactions: meta.transactions || [],
    target_folder_id: meta.target_folder_id || '',
    target_folder_name: meta.target_folder_name || '',
    callback_url: meta.callback_url || ''
  }
};

// WF03b step 6 — flatten all statements' transactions into individual sheet rows.
const statementItems = $('Build Statement Row').all().map(i => i.json);
const rows = [];
for (const s of statementItems) {
  const txs = Array.isArray(s.transactions) ? s.transactions : [];
  for (const t of txs) {
    rows.push({
      json: {
        session_id: s.session_id,
        statement_id: s.statement_id,
        date: t.date || '',
        description: t.description || '',
        counterparty: t.counterparty || '',
        amount: typeof t.amount === 'number' ? t.amount : '',
        currency: t.currency || s.currency || 'UAH',
        debit_credit: t.debit_credit || '',
        balance_after: typeof t.balance_after === 'number' ? t.balance_after : '',
        category: t.category || 'other',
        confidence: typeof t.confidence === 'number' ? t.confidence : 0,
        model_used: t.model_used || 'haiku-4.5'
      }
    });
  }
}
return rows;

// WF03b step 8 — aggregate per-session totals for the Sessions tab update.
// Also propagates callback_url + chat_id + target_folder_* to WF04b.
const statementItems = $('Build Statement Row').all().map(i => i.json);
if (statementItems.length === 0) return [];
const first = statementItems[0];
const sessionId = first.session_id;
const stmts = statementItems.length;
const txTotal = statementItems.reduce((sum, s) => sum + ((s.transactions || []).length), 0);
const lowConfTotal = statementItems.reduce((sum, s) => {
  return sum + (s.transactions || []).filter(t => typeof t.confidence === 'number' && t.confidence < 0.8).length;
}, 0);
return [{
  json: {
    session_id: sessionId,
    chat_id: first.chat_id || 0,
    status: 'building_xlsx',
    statements_count: stmts,
    transactions_total: txTotal,
    low_confidence_count: lowConfTotal,
    callback_url: first.callback_url || '',
    target_folder_id: first.target_folder_id || '',
    target_folder_name: first.target_folder_name || ''
  }
}];
